INSERT INTO feature VALUES('prose-check','workflow','The parsed sentence rules',NULL,'implemented','ordinary',NULL,'`check:prose` parses the corpus comments, the crate READMEs and the rendered diagnostics with spaCy and refuses a passive outside the stated list, a past tense, a stack of four nouns, an `-ing` main verb, a glossary word in another part of speech, and a diagnostic without its what, where and imperative; the committed debt is a ledger keyed by sentence digest. The merge group runs it as a required lane.','workflow-prose','crates/workflow-prose/tests/cli.rs',NULL,'#2919');
